const route = $('Route Intent').first().json;
const configRows = $('Get Config').all();

const bookingRow = configRows.find(
  item => item.json.key === 'booking_url'
);

if (!bookingRow) {
  throw new Error('booking_url not found in Get Config');
}

const booking_url = bookingRow.json.value;

const service = route.service || route.service_name || '';

const reply =
  "Absolutely! I'll send over the booking link so you can choose a convenient time" +
  (service ? " for your " + service : "") +
  ". We're looking forward to seeing you again, " +
  route.name +
  "!";

return [
  {
    json: {
      ...route,
      booking_url,
      response : reply,
      next_state: 'BOOKING_SENT'
    }
  }
];

return [
  {
    json: {
      ...$json,
      response:
        "I'm sorry to hear that. I've passed your message to our team so someone can follow up with you. Please don't hesitate to reach out if you need anything else."
    }
  }
];

return [
  {
    json: {
      ...$json,
      response:
        "Thanks for reaching out! I want to make sure I understand correctly. Could you tell me a little more about what you need help with?"
    }
  }
];

const items = $input.all();

return items
  .filter(item => {
    const messages = item.json.body?.entry?.[0]?.changes?.[0]?.value?.messages;
    return Array.isArray(messages) && messages.length > 0;
  })
  .map(item => {
    const msg = item.json.body.entry[0].changes[0].value.messages[0];
    item.json.body.phone = msg.from;
    item.json.body.message = msg.text?.body || '';
    return item;
  });

const llm = $('Basic LLM Chain').first().json;
const raw = String(llm.output || llm.text || llm.response || llm.content || '').trim();
const patient = $('Fetch Patient Record').first().json;
const msg = $('Webhook').first().json.body.entry[0].changes[0].value.messages[0];

let ai;
try {
  ai = JSON.parse(raw.replace(/^json\s*/i, '').trim());
} catch (error) {
  ai = { intent: 'HUMAN_REQUIRED', reply: 'HUMAN_REQUIRED', next_state: 'HUMAN_REQUIRED' };
}

const intent = String(ai.intent || 'HUMAN_REQUIRED').toUpperCase();
const reply = intent === 'HUMAN_REQUIRED' ? 'HUMAN_REQUIRED' : String(ai.reply || 'HUMAN_REQUIRED').trim();
const routeMap = { BOOKING_INTENT: 'BOOKING', HUMAN_REQUIRED: 'HUMAN', NOT_INTERESTED: 'OPT_OUT' };

return [{ json: {
  patient_id: patient.patient_id,
  phone: String(patient.phone),
  name: patient.first_name,
  first_name: patient.first_name,
  reply,
  intent,
  next_state: String(ai.next_state || routeMap[intent] || 'ACTIVE').toUpperCase(),
  route: routeMap[intent] || 'NORMAL',
  message_id: msg.id,
  incoming_message: String(msg.text && msg.text.body || '')
} }];

// ===== CONFIGURATION =====
const BOOKING_URL = 'https://example.com/book'; // Update with your actual booking URL
const CLINIC = 'Sample Practice';                    // Update with your clinic name
const YES_MEANS_BOOKING = true;

const RULES = [
  { 
    key: 'stop',  
    re: /^(stop|stop all|stopall|unsubscribe|opt ?out|remove me|quit)$/,    
    reply: `Understood. You've been unsubscribed and won't get more promotional messages from ${CLINIC}. Reply START anytime to rejoin.`, 
    state: 'OPTED_OUT', 
    opt: 'YES' 
  },
  { 
    key: 'start', 
    re: /^(start|subscribe|unstop)$/,    
    reply: `Welcome back! 😊 You'll hear from ${CLINIC} again. How can we help?`, 
    state: 'INTERESTED', 
    opt: 'NO' 
  },
  { 
    key: 'book',  
    re: /^(book|book now|book me|book me in|booking|schedule|book an appointment|i want to book|i want to book an appointment)$/,    
    reply: `Absolutely 😊 Here's our booking link: ${BOOKING_URL}`, 
    state: 'BOOKING_SENT', 
    opt: '' 
  },
  { 
    key: 'human', 
    re: /^(human|agent|staff|call me|talk to a person|talk to someone|speak to someone|speak to a person)$/,    
    reply: `Of course, I'll have someone from our team reach out shortly.`, 
    state: 'HUMAN_REQUIRED', 
    opt: '' 
  },
  { 
    key: 'hi',    
    re: /^(hi|hii+|hello|hey|hola|namaste)$/,    
    reply: `Hi! 😊 How can we help you today?`, 
    state: '', 
    opt: '' 
  },
  { 
    key: 'thanks', 
    re: /^(thanks|thank you|thankyou|thx|ty)$/,    
    reply: `You're welcome! 😊`, 
    state: '', 
    opt: '' 
  },
];

if (YES_MEANS_BOOKING) {
  RULES.push({ 
    key: 'yes', 
    re: /^(yes|yes please|yeah|yep|sure|sure please)$/,  
    reply: `Great! 😊 Here's our booking link so you can pick a time: ${BOOKING_URL}`, 
    state: 'BOOKING_SENT', 
    opt: '' 
  });
}

const MEDIA = { 
  key: 'media',  
  reply: `Thanks for sending that! I can only read text messages right now, so I'll have someone from our team take a look 😊`, 
  state: 'HUMAN_REQUIRED', 
  opt: '' 
};

// ===== DEDUPLICATION & PARSING ENGINE =====
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || [];
const out = [];

const build = (root, body, m, v, single) => {
  const id = String(m.id ?? '').trim();
  if (id && sd.seen.includes(id)) return; // Drop duplicates & Meta retries
  if (id) sd.seen.push(id);

  const type = m.type || 'text';
  const raw = type === 'text' ? m.text?.body
    : type === 'button' ? (m.button?.text ?? m.button?.payload)
    : type === 'interactive' ? (m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title)
    : '';

  const message = String(raw ?? '').trim();
  const phone = String(m.from ?? '').replace(/^whatsapp:/i, '').replace(/\D/g, '');

  let ts = m.timestamp;
  const n = Number(ts);
  const iso = Number.isFinite(n) && n > 0 
    ? new Date(n * 1000).toISOString()
    : (typeof ts === 'string' && !isNaN(Date.parse(ts)) ? new Date(ts).toISOString() : new Date().toISOString());

  const t = message.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, '').replace(/\s+/g, ' ').trim();
  const textTypes = ['text', 'button', 'interactive'];
  const rule = !textTypes.includes(type) ? MEDIA : RULES.find(r => r.re.test(t));

  out.push({
    json: {
      ...root,
      ...(single ? { body: single } : {}),
      phone,
      message,
      message_id: id,
      timestamp: iso,
      msg_type: type,
      wa_name: v.contacts?.[0]?.profile?.name ?? '',
      keyword: rule?.key ?? '',
      fast_path: Boolean(rule),
      keyword_reply: rule?.reply ?? '',
      next_state: rule?.state ?? '',
      opt_out: rule?.opt ?? '',
    }
  });
};

for (const item of $input.all()) {
  const root = item.json;
  const body = root.body ?? root;
  let found = false;

  for (const entry of body.entry ?? []) {
    for (const change of entry.changes ?? []) {
      const v = change.value ?? {};
      for (const m of v.messages ?? []) {
        found = true;
        const single = { ...body, entry: [{ ...entry, changes: [{ ...change, value: { ...v, messages: [m] } }] }] };
        build(root, body, m, v, single);
      }
    }
  }

  // Fallback for non-Meta test payloads ({ phone, message }) or Twilio ({ From, Body })
  if (!found && (body.message || body.text || body.Body)) {
    build(root, body, {
      from: body.phone ?? body.From ?? body.from,
      id: body.message_id ?? body.messageId ?? body.MessageSid,
      timestamp: body.timestamp,
      type: 'text',
      text: { body: body.message ?? body.text ?? body.Body },
    }, {}, null);
  }
}

// Keep duplicate cache size manageable
sd.seen = sd.seen.slice(-300);

return out;

const source = $input.first().json;
return [{
  json: {
    ...source,
    reply: source.keyword_reply,
    route: 'FAST_PATH',
    opt_out: source.keyword === 'stop' || source.keyword === 'unsubscribe' ? 'YES' : 'NO',
    human_required: 'NO'
  }
}];

const sd = $getWorkflowStaticData('global');
const now = Date.now();
const TTL = 5 * 60 * 1000; // 5 minute cache limit

const isFresh = Boolean(sd.kbCache && sd.kbTimestamp && (now - sd.kbTimestamp < TTL));

return [{
  json: {
    ...$json,
    cache_hit: isFresh,
    knowledge_base: isFresh ? sd.kbCache : null
  }
}];

const sd = $getWorkflowStaticData('global');

sd.kbCache = $input.all().map(item => item.json);
sd.kbTimestamp = Date.now();

return [{
  json: {
    ...$json,
    cache_hit: false,
    knowledge_base: sd.kbCache
  }
}];

const crm = $('Fetch Patient Record').first().json;
const rows = $input.all().map(item => item.json);
const msg = String($('Webhook').first().json.body.entry[0].changes[0].value.messages[0].text && $('Webhook').first().json.body.entry[0].changes[0].value.messages[0].text.body || '');
const words = msg.toLowerCase().split(/\W+/).filter(word => word.length > 3);
const active = rows.filter(row => String(row.active || '').toUpperCase() === 'YES').filter(row => !row.valid_until || new Date(row.valid_until) >= new Date());
const picked = active.filter(row => {
  const searchable = [row.offer_name, row.name, row.treatment, row.description, row.details, row.type].map(value => String(value || '')).join(' ').toLowerCase();
  return ['offer', 'policy', 'hours', 'booking'].some(word => searchable.includes(word)) || words.some(word => searchable.includes(word));
}).slice(0, 12);
const kb = picked.map(row => {
  const price = row.price ? ' | Price: ' + row.price + (row.currency ? ' ' + row.currency : '') : '';
  const until = row.valid_until ? ' | Until: ' + row.valid_until : '';
  return '- [' + (row.type || 'offer') + '] ' + (row.offer_name || row.name || row.treatment || '') + ': ' + (row.description || row.details || '') + price + until;
}).join(String.fromCharCode(10));
let recentChat = String(crm.recent_chat || '').trim();
try { const parsed = JSON.parse(recentChat); if (Array.isArray(parsed)) recentChat = parsed.map(turn => (turn.role || turn.direction || 'user') + ': ' + (turn.message || turn.content || '')).join(String.fromCharCode(10)); } catch (error) {}
recentChat = recentChat.slice(-4000);
return [{ json: { ...crm, message: msg, recent_chat: recentChat, kb: kb || 'No matching verified business facts.', human_required: picked.length ? 'NO' : 'YES' } }];
